// Build the classification request from the received email.
const SYSTEM = "Tu es l'assistant de triage du service client / ADV d'un vendeur de cuisines. On te donne un mail entrant. Classe-le dans EXACTEMENT une de ces categories: demande_devis, relance_devis, reclamation, demande_information, suivi_commande, annulation, spam, autre. Extrais les champs cles s'ils sont presents (order_ref, quote_ref, budget, contact), sinon null, n'invente rien. Resume en une phrase et propose une action concrete. Reponds UNIQUEMENT par un objet JSON {category, fields:{order_ref,quote_ref,budget,contact}, summary, proposed_action, confidence}. confidence entre 0 et 1.";
const subject = $json.subject || '';
const body = $json.textPlain || $json.text || '';
const from = (typeof $json.from === 'string') ? $json.from : ($json.from && $json.from.text) || '';
return [{ json: { subject, from, body, anthropicBody: { model: 'claude-opus-4-8', max_tokens: 512, system: SYSTEM, messages: [ { role: 'user', content: 'Sujet: ' + subject + '\n\n' + body } ] } } }];

const ROUTE = { demande_devis: 'ADV / Commercial', relance_devis: 'ADV / Commercial', annulation: 'ADV', suivi_commande: 'ADV / Logistique', demande_information: 'Commercial', reclamation: 'SAV', spam: 'Archivage', autre: 'Tri manuel' };
const text = ($json.content && $json.content[0]) ? $json.content[0].text : '{}';
let p;
try { p = JSON.parse(text); } catch (e) { p = { category: 'autre', fields: {}, summary: '', proposed_action: '', confidence: 0 }; }
const src = $('Préparer le contenu du mail').item.json;
return [{ json: { subject: src.subject, from: src.from, category: p.category, route: ROUTE[p.category] || 'Tri manuel', fields: p.fields, summary: p.summary, proposed_action: p.proposed_action, confidence: p.confidence } }];

// Bridge to Alfred (running on the host): one discovery session, one signal per
// triaged mail, then trigger detection. host.docker.internal reaches the host.
const base = 'http://host.docker.internal:8000';
const items = $input.all();
const session = await this.helpers.httpRequest({ method: 'POST', url: base + '/discovery', body: { title: 'Service ADV (mails entrants)', message: 'Signaux issus du triage automatique des mails entrants.' }, json: true });
for (const it of items) {
  await this.helpers.httpRequest({ method: 'POST', url: base + '/discovery/' + session.id + '/signal', body: { label: it.json.category, value: it.json.summary || it.json.subject || '' }, json: true });
}
await this.helpers.httpRequest({ method: 'POST', url: base + '/discovery/' + session.id + '/detect', json: true });
const candidates = await this.helpers.httpRequest({ method: 'GET', url: base + '/discovery/' + session.id + '/opportunities', json: true });
return [{ json: { sessionId: session.id, ingested: items.length, candidates } }];
